10: export function polylineLength(points) {
11:   let total = 0;
12:   for (let i = 0; i < points.length; i++) {
13:     const a = points[i];
14:     const b = points[(i + 1) % points.length];
15:     total += Math.hypot(b.x - a.x, b.y - a.y);
16:   }
17:   return total;
18: }
