20: function dedupe(points, minDist = 1.8) {
21:   const out = [];
22:   for (const p of points) {
23:     const last = out[out.length - 1];
24:     if (!last || Math.hypot(p.x - last.x, p.y - last.y) >= minDist) out.push({ x: p.x, y: p.y });
25:   }
26:   if (out.length > 2) {
27:     const first = out[0];
28:     const last = out[out.length - 1];
29:     if (Math.hypot(first.x - last.x, first.y - last.y) < minDist) out.pop();
30:   }
31:   return out;
32: }
