34: function chaikinClosed(points, iterations = 2) {
35:   let pts = points;
36:   for (let it = 0; it < iterations; it++) {
37:     const out = [];
38:     const n = pts.length;
39:     for (let i = 0; i < n; i++) {
40:       const a = pts[i];
41:       const b = pts[(i + 1) % n];
42:       out.push({ x: a.x * 0.75 + b.x * 0.25, y: a.y * 0.75 + b.y * 0.25 });
43:       out.push({ x: a.x * 0.25 + b.x * 0.75, y: a.y * 0.25 + b.y * 0.75 });
44:     }
45:     pts = out;
46:   }
47:   return pts;
48: }
