50: function catmullRomClosed(points, tess = 7) {
51:   const n = points.length;
52:   if (n < 3) return points.slice();
53:   const out = [];
54:   for (let i = 0; i < n; i++) {
55:     const p0 = points[(i - 1 + n) % n];
56:     const p1 = points[i];
57:     const p2 = points[(i + 1) % n];
58:     const p3 = points[(i + 2) % n];
59:     for (let t = 0; t < tess; t++) {
60:       const u = t / tess;
61:       const u2 = u * u;
62:       const u3 = u2 * u;
63:       const x = 0.5 * ((2 * p1.x) + (-p0.x + p2.x) * u + (2 * p0.x - 5 * p1.x + 4 * p2.x - p3.x) * u2 + (-p0.x + 3 * p1.x - 3 * p2.x + p3.x) * u3);
64:       const y = 0.5 * ((2 * p1.y) + (-p0.y + p2.y) * u + (2 * p0.y - 5 * p1.y + 4 * p2.y - p3.y) * u2 + (-p0.y + 3 * p1.y - 3 * p2.y + p3.y) * u3);
65:       out.push({ x, y });
66:     }
67:   }
68:   return out;
69: }
