78: export function resampleClosedUniform(points, count) {
79:   const n = points.length;
80:   if (n < 2) return points.slice();
81:   const seg = [];
82:   let total = 0;
83:   for (let i = 0; i < n; i++) {
84:     const a = points[i];
85:     const b = points[(i + 1) % n];
86:     const len = Math.hypot(b.x - a.x, b.y - a.y);
87:     seg.push(len);
88:     total += len;
89:   }
90:   const out = [];
91:   const step = total / count;
92:   let target = 0;
93:   let dist = 0;
94:   let idx = 0;
95:   for (let i = 0; i < count; i++) {
96:     target = i * step;
97:     while (dist + seg[idx] < target && idx < n - 1) {
98:       dist += seg[idx];
99:       idx++;
100:     }
101:     const a = points[idx];
102:     const b = points[(idx + 1) % n];
103:     const t = seg[idx] > 0 ? (target - dist) / seg[idx] : 0;
104:     out.push({ x: lerp(a.x, b.x, t), y: lerp(a.y, b.y, t) });
105:   }
106:   return out;
107: }
