109: function segmentsIntersect(a, b, c, d) {
110:   const orient = (p, q, r) => (q.y - p.y) * (r.x - q.x) - (q.x - p.x) * (r.y - q.y);
111:   const o1 = orient(a, b, c);
112:   const o2 = orient(a, b, d);
113:   const o3 = orient(c, d, a);
114:   const o4 = orient(c, d, b);
115:   if (o1 * o2 < -1e-9 && o3 * o4 < -1e-9) return true;
116:   const onSeg = (p, q, r) => Math.min(p.x, q.x) <= r.x + 1e-9 && r.x <= Math.max(p.x, q.x) + 1e-9 &&
117:     Math.min(p.y, q.y) <= r.y + 1e-9 && r.y <= Math.max(p.y, q.y) + 1e-9;
118:   if (Math.abs(o1) < 1e-9 && onSeg(a, b, c)) return true;
119:   if (Math.abs(o2) < 1e-9 && onSeg(a, b, d)) return true;
120:   if (Math.abs(o3) < 1e-9 && onSeg(c, d, a)) return true;
121:   if (Math.abs(o4) < 1e-9 && onSeg(c, d, b)) return true;
122:   return false;
123: }
