125: export function findSelfIntersection(points) {
126:   const n = points.length;
127:   if (n < 8) return false;
128:   const stride = Math.max(1, Math.floor(n / 420));
129:   const pts = [];
130:   for (let i = 0; i < n; i += stride) pts.push(points[i]);
131:   const m = pts.length;
132:   for (let i = 0; i < m; i++) {
133:     const a = pts[i];
134:     const b = pts[(i + 1) % m];
135:     const axMin = Math.min(a.x, b.x), axMax = Math.max(a.x, b.x);
136:     const ayMin = Math.min(a.y, b.y), ayMax = Math.max(a.y, b.y);
137:     for (let j = i + 2; j < m; j++) {
138:       if (i === 0 && j === m - 1) continue;
139:       if (j - i < 2) continue;
140:       const c = pts[j];
141:       const d = pts[(j + 1) % m];
142:       if (Math.max(c.x, d.x) < axMin || Math.min(c.x, d.x) > axMax) continue;
143:       if (Math.max(c.y, d.y) < ayMin || Math.min(c.y, d.y) > ayMax) continue;
144:       if (segmentsIntersect(a, b, c, d)) return true;
145:     }
146:   }
147:   return false;
148: }
