160: /* Count corner groups cyclically. Starting on a non-corner sample keeps a
161:    corner that crosses the start/finish seam from being counted twice. */
162: function measureTurns(curvature, step, threshold) {
163:   const n = curvature.length;
164:   if (!n) return { turns: 0, longest: 0 };
165:   const gapMax = Math.max(1, Math.round(14 / step));
166:   let start = -1;
167:   for (let i = 0; i < n; i++) {
168:     if (curvature[i] <= threshold) { start = i; break; }
169:   }
170:   // The whole lap is one continuous bend.
171:   if (start < 0) return { turns: 1, longest: 0 };
172: 
173:   let turns = 0;
174:   let inTurn = false;
175:   let gap = 0;
176:   let straightBest = 0;
177:   let straightRun = 0;
178:   for (let k = 0; k < n; k++) {
179:     const i = (start + k) % n;
180:     if (curvature[i] > threshold) {
181:       if (!inTurn) { turns++; inTurn = true; }
182:       gap = 0;
183:       straightRun = 0;
184:     } else {
185:       if (inTurn) {
186:         gap++;
187:         if (gap > gapMax) { inTurn = false; gap = 0; }
188:       }
189:       straightRun += step;
190:       if (straightRun > straightBest) straightBest = straightRun;
191:     }
192:   }
193:   return { turns, longest: straightBest };
194: }
