201: export function analyzePreview(rawPoints, opts = {}) {
202:   const prepared = prepareLoop(rawPoints);
203:   const rawLength = polylineLength(prepared);
204:   const bbox = prepared.reduce((b, p) => ({
205:     minX: Math.min(b.minX, p.x), minY: Math.min(b.minY, p.y),
206:     maxX: Math.max(b.maxX, p.x), maxY: Math.max(b.maxY, p.y)
207:   }), { minX: Infinity, minY: Infinity, maxX: -Infinity, maxY: -Infinity });
208: 
209:   const targetLength = opts.targetLength ?? 1900;
210:   const scale = rawLength > 0 ? targetLength / rawLength : 1;
211:   const world = prepared.map((p) => ({ x: p.x * scale, y: p.y * scale }));
212: 
213:   // world-space stats after a uniform resample
214:   const sampleCount = Math.max(260, Math.min(900, Math.round(rawLength / 2)));
215:   const uniform = resampleClosedUniform(world, sampleCount);
216:   const step = targetLength / sampleCount;
217: 
218:   // curvature from heading change over 3 steps
219:   const curv = [];
220:   for (let i = 0; i < sampleCount; i++) {
221:     const look = 3;
222:     const a = uniform[(i - look + sampleCount) % sampleCount];
223:     const b = uniform[i];
224:     const c = uniform[(i + look) % sampleCount];
225:     const a1 = Math.atan2(b.x - a.x, b.y - a.y);
226:     const a2 = Math.atan2(c.x - b.x, c.y - b.y);
227:     const d = wrapAngle(a2 - a1);
228:     const dist = Math.hypot(c.x - a.x, c.y - a.y) || 1;
229:     curv.push(Math.abs(d) / dist);
230:   }
231:   // smooth curvature
232:   const sm = [];
233:   const win = Math.max(2, Math.round(24 / step));
234:   for (let i = 0; i < sampleCount; i++) {
235:     let sum = 0;
236:     for (let k = -win; k <= win; k++) sum += curv[(i + k + sampleCount) % sampleCount];
237:     sm.push(sum / (win * 2 + 1));
238:   }
239: 
240:   // Technical tracks keep the precise 1/100 m corner detector. Smooth loops
241:   // (ovals, circles, flowing sketches) fall back to a lower relative threshold
242:   // so they still report meaningful corner and straight figures.
243:   const cornerThreshold = 1 / 100;
244:   const base = measureTurns(sm, step, cornerThreshold);
245:   const smoothThreshold = Math.max(1 / 340, curvaturePercentile(sm, 0.75) * 0.8);
246:   const smooth = measureTurns(sm, step, smoothThreshold);
247:   let turns = Math.max(base.turns, smooth.turns);
248:   let straightBest = base.turns >= 3 ? base.longest : smooth.longest;
249:   if (smooth.turns === 0) {
250:     turns = Math.max(1, turns);
251:     straightBest = 0;
252:   }
253: 
254:   let minRadius = Infinity;
255:   for (let i = 0; i < sampleCount; i++) {
256:     minRadius = Math.min(minRadius, 1 / Math.max(sm[i], 1e-5));
257:   }
258: 
259:   const closed = prepared.length > 3;
260:   const area = polygonArea(prepared);
261:   const selfIntersects = findSelfIntersection(prepared);
262:   const tooSmall = rawLength < 280 || area < 6000 || (bbox.maxX - bbox.minX) < 80 || (bbox.maxY - bbox.minY) < 80;
263:   const tooFew = dedupe(rawPoints, 2).length < 12;
264: 
265:   return {
266:     prepared, rawLength, scale, bbox, area, selfIntersects, closed,
267:     tooSmall, tooFew,
268:     length: Math.round(targetLength),
269:     turns: Math.max(0, turns),
270:     longestStraight: Math.round(straightBest),
271:     minRadius: Number.isFinite(minRadius) ? Math.round(minRadius) : 0,
272:     valid: closed && !selfIntersects && !tooSmall && !tooFew,
273:     targetLength
274:   };
275: }
