317: const vSub = (a, b) => ({ x: a.x - b.x, y: a.y - b.y });
318: const vCross = (a, b) => a.x * b.y - a.y * b.x;
319: const vDist = (a, b) => Math.hypot(a.x - b.x, a.y - b.y);
320: const vUnit = (a) => {
321:   const len = Math.hypot(a.x, a.y) || 1;
322:   return { x: a.x / len, y: a.y / len };
323: };
