325: // ── real-circuit DNA ─────────────────────────────────────────────────
326: // The templates in circuits.js are sampled centre lines of real Grand Prix
327: // circuits. Each roll mirrors, stretches, rotates and warps one of them with
328: // a smooth displacement field plus a few localised bulges. That keeps the
329: // essential shape language — long straights, proper hairpins, tight street
330: // corners — while producing a brand-new layout every time.
331: const TRACK_TEMPLATES = CIRCUIT_TEMPLATES.map((template) => {
332:   const points = [];
333:   for (let i = 0; i < template.points.length; i += 2) {
334:     points.push({ x: template.points[i], y: template.points[i + 1] });
335:   }
336:   return { name: template.name, points };
337: });
