339: function mutateCircuit(template, rng) {
340:   const points = template.points;
341:   const n = points.length;
342: 
343:   const mirror = rng() < 0.5 ? -1 : 1;
344:   const rotation = rng() * TAU;
345:   const stretchX = 0.92 + rng() * 0.16;
346:   const stretchY = 0.92 + rng() * 0.16;
347:   const warpX = (rng() * 2 - 1) * 0.016;
348:   const warpX2 = (rng() * 2 - 1) * 0.008;
349:   const warpY = (rng() * 2 - 1) * 0.016;
350:   const warpY2 = (rng() * 2 - 1) * 0.008;
351:   const freq1 = 1 + Math.floor(rng() * 2);
352:   const freq2 = 2 + Math.floor(rng() * 2);
353:   const phase1 = rng() * TAU;
354:   const phase2 = rng() * TAU;
355:   const phase3 = rng() * TAU;
356:   const phase4 = rng() * TAU;
357: 
358:   // Normalised distance around the lap, used to place local bulges.
359:   const arc = new Float64Array(n);
360:   let total = 0;
361:   const seg = new Float64Array(n);
362:   for (let i = 0; i < n; i++) {
363:     const a = points[i];
364:     const b = points[(i + 1) % n];
365:     seg[i] = Math.hypot(b.x - a.x, b.y - a.y);
366:     total += seg[i];
367:   }
368:   let acc = 0;
369:   for (let i = 0; i < n; i++) {
370:     arc[i] = acc / total;
371:     acc += seg[i];
372:   }
373: 
374:   // One to three smooth bulges / pinches. These are what turn a familiar
375:   // circuit into a new one without breaking it into a scribble.
376:   const bumps = [];
377:   const bumpCount = 1 + Math.floor(rng() * 3);
378:   for (let k = 0; k < bumpCount; k++) {
379:     bumps.push({
380:       center: rng(),
381:       width: 0.045 + rng() * 0.06,
382:       amp: (rng() * 2 - 1) * (0.012 + rng() * 0.02)
383:     });
384:   }
385: 
386:   const cos = Math.cos(rotation);
387:   const sin = Math.sin(rotation);
388:   return points.map((point, i) => {
389:     let px = (point.x - 0.5) * mirror * stretchX;
390:     let py = (point.y - 0.5) * stretchY;
391: 
392:     px += warpX * Math.sin(TAU * freq1 * py + phase1)
393:       + warpX2 * Math.sin(TAU * freq2 * px + phase2);
394:     py += warpY * Math.sin(TAU * freq1 * px + phase3)
395:       + warpY2 * Math.sin(TAU * freq2 * py + phase4);
396: 
397:     const prev = points[(i - 1 + n) % n];
398:     const next = points[(i + 1) % n];
399:     const tx = next.x - prev.x;
400:     const ty = next.y - prev.y;
401:     const tl = Math.hypot(tx, ty) || 1;
402:     let offset = 0;
403:     for (const bump of bumps) {
404:       let d = Math.abs(arc[i] - bump.center);
405:       d = Math.min(d, 1 - d);
406:       offset += bump.amp * Math.exp(-(d * d) / (2 * bump.width * bump.width));
407:     }
408:     px += (-ty / tl) * offset;
409:     py += (tx / tl) * offset;
410: 
411:     const rx = px * cos - py * sin;
412:     const ry = px * sin + py * cos;
413:     return { x: 0.5 + rx, y: 0.5 + ry };
414:   });
415: }
