417: function filletPolygon(verts, rng) {
418:   const n = verts.length;
419:   const corners = [];
420:   for (let i = 0; i < n; i++) {
421:     const a = verts[(i - 1 + n) % n];
422:     const b = verts[i];
423:     const c = verts[(i + 1) % n];
424:     const uBA = vUnit(vSub(a, b));
425:     const uBC = vUnit(vSub(c, b));
426:     // The angle between the two edges, always measured as the smaller of
427:     // the pair. Reflex corners (interior > 180°) still fillet on the
428:     // outside of the turn, so using the smaller angle keeps the radius
429:     // positive and the arc on the correct side.
430:     const phi = Math.acos(clamp(uBA.x * uBC.x + uBA.y * uBC.y, -1, 1));
431:     const edge = Math.min(vDist(a, b), vDist(b, c));
432:     // Tight corners need enough tangent to make a real hairpin; fast
433:     // sweepers need only a little so the main straight stays long.
434:     let frac;
435:     if (phi < 1.15) frac = 0.18 + rng() * 0.16;
436:     else if (phi > 2.05) frac = 0.07 + rng() * 0.09;
437:     else frac = 0.11 + rng() * 0.13;
438:     const tangent = Math.min(edge * frac, edge * 0.42);
439:     const radius = tangent * Math.tan(phi / 2);
440:     const bisector = vUnit({ x: uBA.x + uBC.x, y: uBA.y + uBC.y });
441:     const offset = radius / Math.sin(phi / 2);
442:     const center = { x: b.x + bisector.x * offset, y: b.y + bisector.y * offset };
443:     const p = { x: b.x + uBA.x * tangent, y: b.y + uBA.y * tangent };
444:     const q = { x: b.x + uBC.x * tangent, y: b.y + uBC.y * tangent };
445:     const aP = Math.atan2(p.y - center.y, p.x - center.x);
446:     const aQ = Math.atan2(q.y - center.y, q.x - center.x);
447:     let sweep = aQ - aP;
448:     while (sweep > Math.PI) sweep -= TAU;
449:     while (sweep < -Math.PI) sweep += TAU;
450:     corners.push({ p, q, center, radius, aP, sweep });
451:   }
452: 
453:   let pts = [];
454:   const straights = [];
455:   const pushArc = (corner, includeStart) => {
456:     const steps = Math.max(5, Math.ceil(Math.abs(corner.sweep) * corner.radius / 0.02));
457:     for (let k = includeStart ? 0 : 1; k <= steps; k++) {
458:       const ang = corner.aP + corner.sweep * (k / steps);
459:       pts.push({
460:         x: corner.center.x + Math.cos(ang) * corner.radius,
461:         y: corner.center.y + Math.sin(ang) * corner.radius
462:       });
463:     }
464:   };
465:   const pushLine = (from, to, includeEnd = true) => {
466:     const steps = Math.max(2, Math.ceil(vDist(from, to) / 0.03));
467:     const last = includeEnd ? steps : steps - 1;
468:     const startIdx = pts.length;
469:     for (let k = 1; k <= last; k++) {
470:       const t = k / steps;
471:       pts.push({ x: from.x + (to.x - from.x) * t, y: from.y + (to.y - from.y) * t });
472:     }
473:     if (pts.length > startIdx) {
474:       straights.push({ start: startIdx, end: pts.length, length: vDist(from, to) });
475:     }
476:   };
