584: export function createTrackData(rawPoints, opts = {}) {
585:   const targetLength = opts.targetLength ?? 1900;
586:   const halfWidth = opts.halfWidth ?? 7.2;
587:   const preview = analyzePreview(rawPoints, { targetLength });
588:   if (!preview.valid) return { valid: false, preview };
589: 
590:   const { prepared } = preview;
591:   const scale = preview.scale;
592:   const named = trackNameFor(rawPoints);
593: 
594:   // smooth points in world units
595:   const center = { x: (preview.bbox.minX + preview.bbox.maxX) / 2, y: (preview.bbox.minY + preview.bbox.maxY) / 2 };
596:   let worldPts = prepared.map((p) => ({ x: (p.x - center.x) * scale, y: (p.y - center.y) * scale }));
597: 
598:   // rotate so tangent at the user's starting point points toward +Z
599:   const start = worldPts[0];
600:   let tangent = { x: 0, y: 1 };
601:   for (let i = 1; i < Math.min(worldPts.length, 20); i++) {
602:     const p = worldPts[i];
603:     const dx = p.x - start.x, dy = p.y - start.y;
604:     if (Math.hypot(dx, dy) > 4) { tangent = { x: dx, y: dy }; break; }
605:   }
606:   const startAngle = Math.atan2(tangent.x, tangent.y);
607:   const cos = Math.cos(-startAngle);
608:   const sin = Math.sin(-startAngle);
609:   worldPts = worldPts.map((p) => {
610:     const dx = p.x - start.x;
611:     const dy = p.y - start.y;
612:     return { x: dx * cos - dy * sin, y: dx * sin + dy * cos };
613:   });
614: 
615:   // uniform resample, keeping the start at index 0
616:   const N = clamp(Math.round(targetLength / 1.15), 900, 2400);
617:   const step = targetLength / N;
618:   const pts = resampleClosedUniform(worldPts, N);
619:   const samples = [];
620:   let minX = Infinity, minZ = Infinity, maxX = -Infinity, maxZ = -Infinity;
621: 
622:   for (let i = 0; i < N; i++) {
623:     const p = pts[i];
624:     const prev = pts[(i - 1 + N) % N];
625:     const next = pts[(i + 1) % N];
626:     let tx = next.x - prev.x;
627:     let tz = next.y - prev.y;
628:     const tl = Math.hypot(tx, tz) || 1;
629:     tx /= tl; tz /= tl;
630:     const nx = tz;
631:     const nz = -tx;
632:     minX = Math.min(minX, p.x); maxX = Math.max(maxX, p.x);
633:     minZ = Math.min(minZ, p.y); maxZ = Math.max(maxZ, p.y);
634:     samples.push({ x: p.x, z: p.y, tx, tz, nx, nz, y: 0, s: i * step });
635:   }
636: 
637:   // signed curvature + smoothing
638:   const rawK = new Float32Array(N);
639:   for (let i = 0; i < N; i++) {
640:     const a = samples[(i - 1 + N) % N];
641:     const b = samples[(i + 1) % N];
642:     const a1 = Math.atan2(a.tx, a.tz);
643:     const a2 = Math.atan2(b.tx, b.tz);
644:     rawK[i] = wrapAngle(a2 - a1) / (2 * step);
645:   }
646:   const K = new Float32Array(N);
647:   const kWin = Math.max(3, Math.round(9 / step));
648:   for (let i = 0; i < N; i++) {
649:     let sum = 0;
650:     for (let k = -kWin; k <= kWin; k++) sum += rawK[(i + k + N) % N];
651:     K[i] = sum / (kWin * 2 + 1);
652:   }
653:   for (let i = 0; i < N; i++) {
654:     samples[i].k = K[i];
655:     samples[i].radius = 1 / Math.max(Math.abs(K[i]), 1e-5);
656:   }
657: 
658:   // corners / kerbs / straights
659:   const cornerFlags = new Uint8Array(N);
660:   const cornerThreshold = 1 / 110;
661:   const cornerGap = Math.round(14 / step);
662:   let inTurn = false;
663:   let gap = 0;
664:   for (let i = 0; i < N; i++) {
665:     const idx = i;
666:     const isTurn = Math.abs(K[idx]) > cornerThreshold;
667:     if (isTurn) {
668:       inTurn = true;
669:       gap = 0;
