761: export class TrackLocator {
762:   constructor(track, cell = 16) {
763:     this.track = track;
764:     this.cell = cell;
765:     this.grid = new Map();
766:     const N = track.N;
767:     for (let i = 0; i < N; i++) {
768:       const s = track.samples[i];
769:       const key = this.key(s.x, s.z);
770:       let arr = this.grid.get(key);
771:       if (!arr) { arr = []; this.grid.set(key, arr); }
772:       arr.push(i);
773:     }
774:     this.lastIndex = 0;
775:   }
776:   key(x, z) {
777:     return `${Math.floor(x / this.cell)},${Math.floor(z / this.cell)}`;
778:   }
779:   nearest(x, z, radius = 2) {
780:     let best = -1;
781:     let bestD = Infinity;
782:     const cx = Math.floor(x / this.cell);
783:     const cz = Math.floor(z / this.cell);
784:     for (let ox = -radius; ox <= radius; ox++) {
785:       for (let oz = -radius; oz <= radius; oz++) {
786:         const arr = this.grid.get(`${cx + ox},${cz + oz}`);
787:         if (!arr) continue;
788:         for (const i of arr) {
789:           const s = this.track.samples[i];
790:           const d = (s.x - x) ** 2 + (s.z - z) ** 2;
791:           if (d < bestD) { bestD = d; best = i; }
792:         }
793:       }
794:     }
795:     if (best === -1) {
796:       const N = this.track.N;
797:       for (let i = 0; i < N; i += 3) {
798:         const s = this.track.samples[i];
799:         const d = (s.x - x) ** 2 + (s.z - z) ** 2;
800:         if (d < bestD) { bestD = d; best = i; }
801:       }
802:     }
803:     if (best >= 0) this.lastIndex = best;
804:     return { index: best, dist: Math.sqrt(bestD) };
805:   }
806: }
