158:     ctx.textBaseline = 'middle';
159:     ctx.fillText(text, w / 2, sub ? h / 2 - 14 : h / 2 + 2);
160:     if (sub) {
161:       ctx.fillStyle = '#ff4d1f';
162:       ctx.font = '600 26px Rajdhani';
163:       ctx.fillText(sub, w / 2, h / 2 + 42);
164:     }
165:   });
166:   return canvasTexture(c);
167: }
