170:    Geometry helpers
171:    ═══════════════════════════════════════════════════════════════════ */
172: 
173: function ribbonGeometry(track, offA, offB, y, { tile = 8, uA = 0, uB = 1 } = {}) {
174:   const N = track.N;
175:   const pos = [];
176:   const uv = [];
177:   const idx = [];
178:   const total = track.length;
179:   for (let i = 0; i <= N; i++) {
180:     const s = track.samples[i % N];
181:     const a = offA;
182:     const b = offB;
183:     pos.push(s.x + s.nx * a, y, s.z + s.nz * a);
184:     pos.push(s.x + s.nx * b, y, s.z + s.nz * b);
185:     const v = (i === N ? total : s.s) / tile;
186:     uv.push(uA, v, uB, v);
187:   }
188:   for (let i = 0; i < N; i++) {
189:     const a = i * 2;
190:     idx.push(a, a + 2, a + 1, a + 1, a + 2, a + 3);
191:   }
192:   const geo = new THREE.BufferGeometry();
193:   geo.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
194:   geo.setAttribute('uv', new THREE.Float32BufferAttribute(uv, 2));
195:   geo.setIndex(idx);
196:   geo.computeVertexNormals();
197:   return geo;
198: }
199: 
200: function segmentRibbonGeometry(track, offsetA, offsetB, y, activeFn, colorFn, tileLen = 2.5) {
201:   const N = track.N;
202:   const pos = [];
203:   const col = [];
204:   const idx = [];
205:   let v = 0;
206:   for (let i = 0; i < N; i++) {
207:     if (!activeFn(i)) continue;
208:     const s = track.samples[i];
209:     const n = track.samples[(i + 1) % N];
210:     const oA = typeof offsetA === 'function' ? offsetA(i) : offsetA;
211:     const oB = typeof offsetB === 'function' ? offsetB(i) : offsetB;
212:     const lo = Math.min(oA, oB);
213:     const hi = Math.max(oA, oB);
214:     const ax = s.x + s.nx * lo, az = s.z + s.nz * lo;
215:     const bx = s.x + s.nx * hi, bz = s.z + s.nz * hi;
216:     const cx = n.x + n.nx * lo, cz = n.z + n.nz * lo;
217:     const dx = n.x + n.nx * hi, dz = n.z + n.nz * hi;
218:     const base = pos.length / 3;
219:     pos.push(ax, y, az, bx, y, bz, cx, y, cz, dx, y, dz);
220:     const c = colorFn(i, Math.floor(s.s / tileLen));
221:     for (let k = 0; k < 4; k++) col.push(c.r, c.g, c.b);
222:     idx.push(base, base + 2, base + 1, base + 1, base + 2, base + 3);
223:     v++;
224:   }
225:   const geo = new THREE.BufferGeometry();
226:   geo.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
227:   geo.setAttribute('color', new THREE.Float32BufferAttribute(col, 3));
228:   geo.setIndex(idx);
229:   geo.computeVertexNormals();
230:   return geo;
231: }
232: 
233: function planeAt(sample, width, depth, y, material, angleOffset = 0) {
234:   const geo = new THREE.PlaneGeometry(width, depth);
235:   geo.rotateX(-Math.PI / 2);
236:   const mesh = new THREE.Mesh(geo, material);
237:   mesh.position.set(sample.x, y, sample.z);
238:   mesh.rotation.y = Math.atan2(sample.tx, sample.tz) + angleOffset;
239:   mesh.receiveShadow = true;
240:   return mesh;
241: }
