247: function createSky(sunDir) {
248:   const vertex = `
249:     varying vec3 vDir;
250:     void main() {
251:       vDir = normalize(position);
252:       gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
253:     }`;
254:   const fragment = `
255:     varying vec3 vDir;
256:     uniform vec3 uSun;
257:     void main() {
258:       vec3 d = normalize(vDir);
259:       float h = clamp(d.y, -0.15, 1.0);
260:       vec3 horizon = vec3(0.83, 0.80, 0.72);
261:       vec3 mid = vec3(0.60, 0.70, 0.76);
262:       vec3 top = vec3(0.24, 0.43, 0.63);
263:       vec3 col = mix(horizon, mid, smoothstep(0.0, 0.22, h));
264:       col = mix(col, top, smoothstep(0.18, 0.72, h));
265:       float sun = max(dot(d, normalize(uSun)), 0.0);
266:       col += vec3(1.0, 0.62, 0.30) * pow(sun, 24.0) * 0.45;
267:       col += vec3(1.0, 0.78, 0.5) * pow(sun, 500.0) * 1.6;
268:       col = mix(col, vec3(0.95, 0.72, 0.52), pow(1.0 - max(h, 0.0), 8.0) * 0.22);
269:       gl_FragColor = vec4(col, 1.0);
270:     }`;
271:   const mat = new THREE.ShaderMaterial({
272:     vertexShader: vertex,
273:     fragmentShader: fragment,
274:     uniforms: { uSun: { value: sunDir.clone().normalize() } },
275:     side: THREE.BackSide,
276:     depthWrite: false,
277:     fog: false
278:   });
279:   const mesh = new THREE.Mesh(new THREE.SphereGeometry(4200, 32, 18), mat);
280:   mesh.frustumCulled = false;
281:   return mesh;
282: }
