284: function cloudTexture() {
285:   const c = makeTextCanvas(256, 128, (ctx, w, h) => {
286:     ctx.clearRect(0, 0, w, h);
287:     for (let i = 0; i < 18; i++) {
288:       const x = 40 + Math.random() * (w - 80);
289:       const y = 45 + Math.random() * (h - 70);
290:       const r = 18 + Math.random() * 34;
291:       const g = ctx.createRadialGradient(x, y, 0, x, y, r);
292:       g.addColorStop(0, 'rgba(255,255,255,.5)');
293:       g.addColorStop(1, 'rgba(255,255,255,0)');
294:       ctx.fillStyle = g;
295:       ctx.beginPath(); ctx.arc(x, y, r, 0, TAU); ctx.fill();
296:     }
297:   });
298:   return canvasTexture(c);
299: }
