334: function drawMenuMinimap(last) {
335:   const canvas = dom.menuMinimap;
336:   const ctx = canvas.getContext('2d');
337:   const w = canvas.width, h = canvas.height;
338:   ctx.clearRect(0, 0, w, h);
339:   ctx.fillStyle = 'rgba(5,7,10,.4)';
340:   ctx.fillRect(0, 0, w, h);
341: 
342:   // faint grid
343:   ctx.strokeStyle = 'rgba(255,255,255,.035)';
344:   ctx.lineWidth = 1;
345:   for (let x = 20; x < w; x += 42) {
346:     ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, h); ctx.stroke();
347:   }
348:   for (let y = 16; y < h; y += 42) {
349:     ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(w, y); ctx.stroke();
350:   }
351: 
352:   if (!last) {
353:     ctx.save();
354:     ctx.translate(w / 2, h / 2);
355:     ctx.setLineDash([4, 10]);
356:     ctx.strokeStyle = 'rgba(255,77,31,.28)';
357:     ctx.lineWidth = 1.5;
358:     ctx.beginPath();
359:     ctx.ellipse(0, 0, w * 0.33, h * 0.27, -0.18, 0, TAU);
360:     ctx.stroke();
361:     ctx.setLineDash([]);
362:     ctx.strokeStyle = 'rgba(255,255,255,.08)';
363:     ctx.beginPath(); ctx.moveTo(-9, 0); ctx.lineTo(9, 0); ctx.moveTo(0, -9); ctx.lineTo(0, 9); ctx.stroke();
364:     ctx.restore();
365:     return;
366:   }
367: 
368:   const preview = analyzePreview(last.points, { targetLength: 1900 });
369:   if (!preview.prepared.length) return;
370:   let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
371:   for (const p of preview.prepared) {
372:     minX = Math.min(minX, p.x); maxX = Math.max(maxX, p.x);
373:     minY = Math.min(minY, p.y); maxY = Math.max(maxY, p.y);
374:   }
375:   const pad = 30;
376:   const scale = Math.min((w - pad * 2) / (maxX - minX || 1), (h - pad * 2) / (maxY - minY || 1));
377:   const ox = (w - (maxX - minX) * scale) / 2 - minX * scale;
378:   const oy = (h - (maxY - minY) * scale) / 2 - minY * scale;
379:   const map = (p) => ({ x: p.x * scale + ox, y: p.y * scale + oy });
380: 
381:   ctx.save();
382:   ctx.lineJoin = 'round';
383:   ctx.lineCap = 'round';
384:   ctx.beginPath();
385:   preview.prepared.forEach((p, i) => {
386:     const q = map(p);
387:     if (i === 0) ctx.moveTo(q.x, q.y); else ctx.lineTo(q.x, q.y);
388:   });
389:   ctx.closePath();
390:   ctx.strokeStyle = 'rgba(255,77,31,.16)';
391:   ctx.lineWidth = 13;
392:   ctx.shadowColor = 'rgba(255,77,31,.7)';
393:   ctx.shadowBlur = 18;
394:   ctx.stroke();
395:   ctx.shadowBlur = 0;
396:   ctx.strokeStyle = 'rgba(7,9,12,.9)';
397:   ctx.lineWidth = 7;
398:   ctx.stroke();
399:   ctx.strokeStyle = '#f3efe5';
400:   ctx.lineWidth = 2.4;
401:   ctx.stroke();
402: 
403:   // start marker
404:   const start = map(preview.prepared[0]);
405:   ctx.fillStyle = '#ff4d1f';
406:   ctx.beginPath();
407:   ctx.arc(start.x, start.y, 3.5, 0, TAU);
408:   ctx.fill();
409:   ctx.strokeStyle = 'rgba(255,77,31,.8)';
410:   ctx.lineWidth = 1;
411:   ctx.beginPath();
412:   ctx.arc(start.x, start.y, 8, 0, TAU);
413:   ctx.stroke();
