1428:   push(race.player.history, playerProgress());
1429:   for (const a of race.ai) {
1430:     const progress = a.finished ? race.totalLaps : Math.min(race.totalLaps, a.dist / race.track.length);
1431:     push(a.history, progress);
1432:   }
1433: }
1434: 
1435: function gapToLeaderSeconds(leader, progress, speed) {
1436:   const history = leader.history;
1437:   if (!history || history.length < 2) return 0;
1438:   const first = history[0];
1439:   const last = history[history.length - 1];
1440:   if (progress >= last.p) return 0;
1441:   if (progress < first.p) {
1442:     // Before the leader's first sample (the grid): no elapsed race time yet.
1443:     if (race.time < 600) return 0;
1444:     const metres = (first.p - progress) * race.track.length;
1445:     return metres / Math.max(24, speed);
1446:   }
1447:   // Binary search for the first timeline sample at or beyond this progress.
1448:   let lo = 0, hi = history.length - 1;
1449:   while (lo < hi) {
1450:     const mid = (lo + hi) >> 1;
1451:     if (history[mid].p >= progress) hi = mid; else lo = mid + 1;
1452:   }
1453:   const b = history[lo];
1454:   const a = history[Math.max(0, lo - 1)];
1455:   if (b === a) return Math.max(0, (race.time - b.t) / 1000);
1456:   const f = clamp((progress - a.p) / Math.max(1e-6, b.p - a.p), 0, 1);
1457:   const tAt = a.t + (b.t - a.t) * f;
1458:   return Math.max(0, (race.time - tAt) / 1000);
1459: }
