1461: function getStandings() {
1462:   const p = race.player;
1463:   const playerP = playerProgress();
1464:   const rows = [{
1465:     name: 'YOU', color: playerPaint, progress: playerP, history: p.history,
1466:     speed: Math.abs(p.vLong), finishTime: p.finishTime,
1467:     isPlayer: true, lap: Math.min(race.totalLaps, p.lapsCompleted + 1), finished: p.finished
1468:   }];
1469:   for (const a of race.ai) {
1470:     const raw = a.dist / race.track.length;
1471:     rows.push({
1472:       name: a.name, color: a.color, progress: a.finished ? race.totalLaps : Math.min(race.totalLaps, raw),
1473:       history: a.history, speed: a.speed, finishTime: a.finishTime,
1474:       isPlayer: false, lap: clamp(Math.floor(a.dist / race.track.length) + 1, 1, race.totalLaps),
1475:       finished: a.finished
1476:     });
1477:   }
1478:   rows.sort((a, b) => {
1479:     if (a.finished && b.finished) return a.finishTime - b.finishTime;
1480:     if (a.finished) return -1;
1481:     if (b.finished) return 1;
1482:     return b.progress - a.progress;
1483:   });
1484:   return rows;
1485: }
