1487: /* ═══════════════════════════════════════════════════════════════════
1488:    Player physics
1489:    ═══════════════════════════════════════════════════════════════════ */
1490: const DUST_COLOR = new THREE.Color(0xc9b28a);
1491: const SMOKE_COLOR = new THREE.Color(0xdad7d0);
1492: let emitAccum = 0;
1493: let minimapFrame = 0;
1494: 
1495: // Arcade-first handling. The car turns in almost immediately, carries more
1496: // cornering force than a real F1 car, and bleeds off sideways slide quickly so
1497: // the nose goes where you point it instead of washing wide into the scenery.
1498: const HANDLING = {
1499:   steerLowSpeed: 0.60,   // max steering angle at a crawl (rad)
1500:   steerHighSpeed: 0.19,  // max steering angle at speed (rad)
1501:   steerSpeedRef: 58,
1502:   steerResponse: 18,     // how fast your input reaches the wheels
1503:   yawResponse: 15,       // how fast the chassis follows the wheels
1504:   gripTrack: 46,         // lateral acceleration budget on asphalt (m/s²)
1505:   gripKerb: 38,
1506:   gripOffroad: 27,
1507:   gripHandbrake: 19,
1508:   sideGripTrack: 12.5,   // how quickly sideways velocity is killed
1509:   sideGripKerb: 11,
1510:   sideGripOffroad: 5.5,
1511:   sideGripHandbrake: 2.1,
1512:   offroadPower: 0.55,    // engine output on grass, so you can drive back
1513:   offroadDrag: 5.5
1514: };
1515: 
1516: // The car drives its own throttle and brakes. The player owns the steering;
1517: // W/S are always available as a direct override for extra speed or stopping.
1518: const AUTODRIVE = {
1519:   lateral: 31,        // cornering budget used to plan safe corner speeds (m/s²)
1520:   brakeDecel: 24,     // braking force assumed when looking ahead (m/s²)
1521:   maxSpeed: 84,       // cruise ceiling in m/s (≈302 km/h)
1522:   offroadMax: 30,     // don't keep charging across the grass
1523:   minSpeed: 20,
1524:   cruiseThrottle: 0.4 // throttle that balances drag near the target speed
1525: };
1526: 
1527: function autoDriveDemand(p, track) {
1528:   const N = track.N;
1529:   const base = Math.floor((((p.sNorm % 1) + 1) % 1) * N) % N;
1530:   const speed = Math.max(0, p.vLong);
1531:   const lookAhead = clamp(55 + speed * 1.55, 55, 190);
1532:   const stride = Math.max(1, Math.round(5 / track.step));
1533:   const maxSteps = Math.round(lookAhead / track.step);
1534:   let target = AUTODRIVE.maxSpeed;
1535: 
1536:   // Scan the road ahead and find the fastest speed we can still brake down to
1537:   // every upcoming corner from. This does the "when do I lift?" thinking.
1538:   for (let d = 0; d <= maxSteps; d += stride) {
1539:     const s = track.samples[(base + d) % N];
1540:     const radius = Math.max(1 / Math.max(Math.abs(s.k), 1e-5), 24);
1541:     const corner = Math.sqrt(AUTODRIVE.lateral * radius);
1542:     const dist = d * track.step;
1543:     target = Math.min(target, Math.sqrt(corner * corner + 2 * AUTODRIVE.brakeDecel * dist));
1544:   }
1545:   if (p.offroad) target = Math.min(target, AUTODRIVE.offroadMax);
1546:   target = clamp(target, AUTODRIVE.minSpeed, AUTODRIVE.maxSpeed);
1547: 
1548:   const gap = target - speed;
1549:   const throttle = clamp(AUTODRIVE.cruiseThrottle + gap * 0.55, 0, 1);
1550:   const brake = speed > target + 0.8
1551:     ? clamp((speed - target - 0.8) / 5, 0.12, 1)
1552:     : 0;
1553:   return { throttle, brake, target };
1554: }
1555: 
1556: function readControls() {
1557:   const active = race.state === 'racing';
1558:   return {
1559:     active,
1560:     gas: active && (input.gas || input.touchGas),
1561:     brake: active && (input.brake || input.touchBrake),
1562:     steer: active ? ((input.left || input.touchLeft ? 1 : 0) - (input.right || input.touchRight ? 1 : 0)) : 0,
1563:     handbrake: active && input.handbrake
1564:   };
1565: }
1566: 
1567: function updatePlayerPhysics(dt) {
1568:   const p = race.player;
1569:   const tr = race.track;
1570:   const controls = readControls();
1571:   const manualGas = controls.gas;
1572:   const manualBrake = controls.brake;
1573:   const handbrake = controls.handbrake;
1574: 
1575:   let throttleDemand = 0;
1576:   let brakeDemand = 0;
1577:   let assistState = 'auto';
1578: 
1579:   if (controls.active) {
1580:     if (manualBrake) {
1581:       // Player brake always wins — it is stronger than the auto brake.
1582:       brakeDemand = 1;
1583:       assistState = 'manual';
1584:     } else if (manualGas) {
1585:       // Player throttle overrides the speed planner so you can chase a faster lap.
1586:       throttleDemand = 1;
1587:       assistState = 'manual';
1588:     } else if (!handbrake) {
1589:       const auto = autoDriveDemand(p, race.track);
1590:       throttleDemand = auto.throttle;
1591:       brakeDemand = auto.brake;
1592:       assistState = auto.brake > 0.15 ? 'auto-brake' : 'auto';
1593:     } else {
1594:       assistState = 'manual';
1595:     }
1596:   }
1597:   p.assistState = assistState;
1598: 
1599:   p.throttle = damp(p.throttle, throttleDemand, 11, dt);
1600:   p.brake = damp(p.brake, brakeDemand, 16, dt);
1601:   p.steer = damp(p.steer, controls.steer, HANDLING.steerResponse, dt);
1602: 
1603:   const speed0 = Math.hypot(p.vel.x, p.vel.z);
1604:   const f0x = Math.sin(p.yaw), f0z = Math.cos(p.yaw);
1605:   const vLong0 = p.vel.x * f0x + p.vel.z * f0z;
1606: 
1607:   const maxSteer = lerp(
1608:     HANDLING.steerLowSpeed,
1609:     HANDLING.steerHighSpeed,
1610:     clamp(speed0 / HANDLING.steerSpeedRef, 0, 1)
1611:   );
1612:   const steerAngle = p.steer * maxSteer;
1613:   const gripAccel = p.offroad
1614:     ? HANDLING.gripOffroad
1615:     : handbrake
1616:       ? HANDLING.gripHandbrake
1617:       : p.onKerb
1618:         ? HANDLING.gripKerb
1619:         : HANDLING.gripTrack;
1620:   const maxYaw = gripAccel / Math.max(4, speed0);
1621:   let yawTarget = (vLong0 / 3.05) * Math.tan(steerAngle);
1622:   if (handbrake) yawTarget *= 1.55;
1623:   yawTarget = clamp(yawTarget, -maxYaw, maxYaw);
1624:   p.yawRate = damp(p.yawRate, yawTarget, HANDLING.yawResponse, dt);
1625:   p.yaw += p.yawRate * dt;
1626:   p.yaw = ((p.yaw + Math.PI) % TAU + TAU) % TAU - Math.PI;
1627: 
1628:   const fx = Math.sin(p.yaw), fz = Math.cos(p.yaw);
1629:   const rx = Math.cos(p.yaw), rz = -Math.sin(p.yaw);
1630: 
1631:   let vLong = p.vel.x * fx + p.vel.z * fz;
1632:   let vLat = p.vel.x * rx + p.vel.z * rz;
1633: 
1634:   const drs = race.state === 'racing' && vLong > 55 && Math.abs(p.lastK || 0) < 1 / 420 && p.throttle > 0.35;
1635:   p.drs = drs;
1636: 
1637:   let accel = 0;
1638:   if (p.throttle > 0.01) {
1639:     const maxSpeed = drs ? 96 : 90;
1640:     const ratio = clamp(vLong / maxSpeed, -1, 1);
1641:     const engine = 18.5 * Math.max(0, 1 - ratio * ratio);
1642:     accel += engine * p.throttle * (p.offroad ? HANDLING.offroadPower : 1);
1643:   }
1644:   if (p.brake > 0.01) {
1645:     if (vLong > 0.35) accel -= 33 * p.brake;
1646:     else accel -= 6.8 * p.brake;
1647:   }
1648:   if (handbrake) accel -= 9;
1649:   const dragCoef = drs ? 0.000165 : 0.00022;
1650:   const drag = dragCoef * vLong * Math.abs(vLong) + 0.6 * Math.sign(vLong) + (p.offroad ? HANDLING.offroadDrag : 0);
1651:   accel -= drag;
1652:   vLong += accel * dt;
1653:   if (vLong < -12) vLong = -12;
1654:   if (p.throttle < 0.02 && p.brake < 0.02 && !handbrake && Math.abs(vLong) < 0.2) vLong = 0;
1655: 
1656:   const sideGrip = p.offroad
1657:     ? HANDLING.sideGripOffroad
1658:     : handbrake
1659:       ? HANDLING.sideGripHandbrake
1660:       : p.onKerb
1661:         ? HANDLING.sideGripKerb
1662:         : HANDLING.sideGripTrack;
1663:   vLat *= Math.exp(-sideGrip * dt);
1664: 
1665:   p.vLong = vLong;
1666:   p.vLat = vLat;
1667:   p.vel.x = fx * vLong + rx * vLat;
1668:   p.vel.z = fz * vLong + rz * vLat;
1669:   p.pos.x += p.vel.x * dt;
1670:   p.pos.z += p.vel.z * dt;
1671: 
1672:   const near = nearestTrackSample(tr, p.pos.x, p.pos.z, p.lastIndex);
1673:   const sample = tr.samples[near.index];
1674:   p.lastIndex = near.index;
1675:   p.sNorm = (near.index % tr.N) / tr.N;
1676:   p.trackDist = near.dist;
1677:   p.lateral = (p.pos.x - sample.x) * sample.nx + (p.pos.z - sample.z) * sample.nz;
1678:   p.lastK = sample.k;
1679:   p.offroad = near.dist > tr.halfWidth + 1.15;
1680:   p.onKerb = !p.offroad && near.dist > tr.halfWidth - 0.55 && near.dist < tr.halfWidth + 1.6;
1681:   if (p.offroad) {
1682:     p.offTimer += dt * (near.dist > tr.halfWidth + 25 ? 2 : 1);
1683:   } else {
1684:     p.offTimer = Math.max(0, p.offTimer - dt * 2.5);
1685:   }
1686:   if (race.state === 'racing' && p.offTimer > 2.7) recoverPlayer();
1687: 
1688:   const kmh = Math.abs(vLong) * 3.6;
1689:   if (race.state === 'racing') p.topSpeed = Math.max(p.topSpeed, kmh);
1690: }
