1692: function updatePlayerVisual(dt) {
1693:   const p = race.player;
1694:   const car = race.playerCar;
1695:   car.root.position.set(p.pos.x, 0, p.pos.z);
1696:   car.root.rotation.y = p.yaw;
1697: 
1698:   const longAccel = (p.vLong - p.prevVLong) / Math.max(dt, 0.001);
1699:   p.prevVLong = p.vLong;
1700:   car.body.rotation.x = damp(car.body.rotation.x, clamp(-longAccel * 0.0022, -0.055, 0.055), 7, dt);
1701:   car.body.rotation.z = damp(car.body.rotation.z, clamp(p.vLong * p.yawRate * 0.0032, -0.07, 0.07), 7, dt);
1702: 
1703:   const steerVisual = p.steer * lerp(
1704:     HANDLING.steerLowSpeed * 0.82,
1705:     HANDLING.steerHighSpeed * 1.2,
1706:     clamp(Math.abs(p.vLong) / HANDLING.steerSpeedRef, 0, 1)
1707:   );
1708:   for (const w of car.wheels) {
1709:     w.spin.rotation.x += (p.vLong / w.radius) * dt;
1710:     if (w.front) w.steer.rotation.y = damp(w.steer.rotation.y, steerVisual, 18, dt);
1711:   }
1712:   car.setBrake(p.brake > 0.08 || race.state === 'finished');
1713:   car.setDRS(p.drs);
1714: 
1715:   // tyre smoke and grass dust
1716:   const slip = Math.abs(p.vLat);
1717:   const speed = Math.abs(p.vLong);
1718:   const rate = p.offroad && speed > 4 ? 42 : (slip > 2.4 && speed > 6 ? 26 : 0);
1719:   if (rate && race.state !== 'countdown') {
1720:     emitAccum += dt * rate;
1721:     while (emitAccum >= 1) {
1722:       emitAccum -= 1;
1723:       const fx = Math.sin(p.yaw), fz = Math.cos(p.yaw);
1724:       const rx = Math.cos(p.yaw), rz = -Math.sin(p.yaw);
1725:       const side = Math.random() > 0.5 ? 1 : -1;
1726:       const x = p.pos.x - fx * 1.65 + rx * side * 0.85;
1727:       const z = p.pos.z - fz * 1.65 + rz * side * 0.85;
1728:       const color = p.offroad ? DUST_COLOR : SMOKE_COLOR;
1729:       race.smoke.emit(x, 0.22, z, color, p.offroad ? 0.9 : 0.7, p.offroad ? 1.25 : 1.0, p.offroad ? 2.4 : 1.6);
1730:     }
1731:   }
1732: }
1733: 
1734: function nearestTrackSample(track, x, z, hint = -1, windowMeters = 26) {
1735:   const N = track.N;
1736:   let best = -1;
1737:   let bestD = Infinity;
1738:   if (Number.isInteger(hint) && hint >= 0 && hint < N) {
1739:     const span = Math.max(6, Math.round(windowMeters / track.step));
1740:     for (let k = -span; k <= span; k++) {
1741:       const i = (hint + k + N) % N;
1742:       const s = track.samples[i];
1743:       const d = (s.x - x) ** 2 + (s.z - z) ** 2;
1744:       if (d < bestD) { bestD = d; best = i; }
1745:     }
1746:     // If the car is well off the road (or has been recovered), fall back to the
1747:     // spatial lookup so it can always find its way back to the nearest asphalt.
1748:     if (best >= 0 && bestD > (track.halfWidth + 36) ** 2) {
1749:       const global = race.locator.nearest(x, z);
1750:       const d = global.dist * global.dist;
1751:       if (global.index >= 0 && d < bestD) { bestD = d; best = global.index; }
1752:     }
1753:   }
1754:   if (best < 0) {
1755:     const global = race.locator.nearest(x, z);
1756:     best = global.index >= 0 ? global.index : 0;
1757:     bestD = global.dist * global.dist;
1758:   }
1759:   return { index: best, dist: Math.sqrt(bestD) };
1760: }
1761: 
1762: function trackDistanceAt(track, index, x, z) {
1763:   const s = track.samples[index];
1764:   const along = (x - s.x) * s.tx + (z - s.z) * s.tz;
1765:   return (s.s ?? index * track.step) + clamp(along, -track.step, track.step);
1766: }
1767: 
1768: function unwrapTrackDistance(candidate, reference, length) {
1769:   let out = candidate;
1770:   const half = length * 0.5;
1771:   while (out - reference > half) out -= length;
1772:   while (out - reference < -half) out += length;
1773:   return out;
1774: }
1775: 
1776: function recoverPlayer(showToast = true) {
1777:   const p = race.player;
1778:   const near = nearestTrackSample(race.track, p.pos.x, p.pos.z, p.lastIndex);
1779:   const s = race.track.samples[near.index];
1780:   p.pos = { x: s.x, z: s.z };
1781:   p.vel = { x: 0, z: 0 };
1782:   p.vLong = 0; p.vLat = 0;
1783:   p.yaw = Math.atan2(s.tx, s.tz);
1784:   p.offroad = false;
1785:   p.offTimer = 0;
1786:   p.lastIndex = near.index;
1787:   p.sNorm = (near.index % race.track.N) / race.track.N;
1788:   p.progressDist = unwrapTrackDistance(trackDistanceAt(race.track, near.index, s.x, s.z), p.progressDist, race.track.length);
1789:   race.locator.lastIndex = near.index;
1790:   // Cut the camera with the car rather than letting it swoop across the
1791:   // circuit to the recovery point.
1792:   race.camYaw = p.yaw;
1793:   race.cameraReady = false;
1794:   race.camLook.set(s.x + Math.sin(p.yaw) * 7, 0.92, s.z + Math.cos(p.yaw) * 7);
1795:   race.smoke.reset();
1796:   if (showToast) {
1797:     toast('Recovered to the racing line');
1798:     audio.tone(330, 0.1, 0.04, 'triangle');
1799:   }
1800: }
