1802: /* ═══════════════════════════════════════════════════════════════════
1803:    Lap logic
1804:    ═══════════════════════════════════════════════════════════════════ */
1805: function completeLap() {
1806:   const p = race.player;
1807:   const lapTime = race.time - p.lapStart;
1808:   if (lapTime > 3000) {
1809:     p.lastLap = lapTime;
1810:     if (!p.bestLap || lapTime < p.bestLap) {
1811:       p.bestLap = lapTime;
1812:       writeBest(race.track.seed, lapTime);
1813:       toast(`NEW BEST LAP · ${formatTime(lapTime)}`);
1814:     }
1815:   }
1816:   p.lapsCompleted++;
1817:   p.lapStart = race.time;
1818:   p.sectors = [false, false, false];
1819:   if (p.lapsCompleted >= race.totalLaps) {
1820:     finishRace();
1821:   } else if (p.lapsCompleted === race.totalLaps - 1) {
1822:     showRaceMessage('FINAL LAP', 'EVERYTHING YOU HAVE', 2300, true);
1823:     audio.tone(880, 0.18, 0.06, 'triangle');
1824:   } else {
1825:     showRaceMessage(`LAP ${p.lapsCompleted + 1} / ${race.totalLaps}`, 'KEEP IT CLEAN', 1900);
1826:     audio.tone(660, 0.1, 0.04, 'triangle');
1827:   }
1828: }
1829: 
1830: function updatePlayerProgress(dt) {
1831:   const p = race.player;
1832:   if (p.finished) return;
1833:   const tr = race.track;
1834:   const L = tr.length;
1835:   const near = nearestTrackSample(tr, p.pos.x, p.pos.z, p.lastIndex);
1836:   const candidate = unwrapTrackDistance(
1837:     trackDistanceAt(tr, near.index, p.pos.x, p.pos.z),
1838:     p.progressDist,
1839:     L
1840:   );
1841: 
1842:   // A car can only advance a sensible distance in one physics step. Clamping
1843:   // rejected huge jumps from nearby track sections while still letting the
1844:   // progress catch up after a recovery.
1845:   const allowed = Math.max(16, Math.abs(p.vLong) * Math.max(dt, 0.001) * 4 + 3);
1846:   const delta = candidate - p.progressDist;
1847:   p.progressDist += Math.abs(delta) <= allowed ? delta : clamp(delta, -allowed, allowed);
1848:   p.lastIndex = near.index;
1849:   p.trackDist = near.dist;
1850:   p.sNorm = (((p.progressDist % L) + L) % L) / L;
1851: 
1852:   // Hidden checkpoints. The lap only counts after every gate has been crossed
1853:   // in order, which keeps the timing tower honest even on circuits that fold
1854:   // back alongside themselves.
1855:   const cpCount = race.checkpoints.length;
1856:   const cpSpacing = L / cpCount;
1857:   if (p.cpArmed) {
1858:     if (p.progressDist >= (p.lapsCompleted + 1) * L) {
1859:       p.cpArmed = false;
1860:       p.cpNext = 1;
1861:       completeLap();
1862:     }
1863:   } else {
1864:     const target = p.lapsCompleted * L + p.cpNext * cpSpacing;
1865:     if (p.progressDist >= target) {
1866:       if (p.cpNext >= cpCount - 1) {
1867:         p.cpArmed = true;
1868:         p.cpNext = 0;
1869:       } else {
1870:         p.cpNext++;
1871:       }
1872:     }
1873:   }
1874: 
1875:   const lapFrac = (((p.progressDist % L) + L) % L) / L;
1876:   if (lapFrac > 0.13) p.sectors[0] = true;
1877:   if (lapFrac > 0.38) p.sectors[1] = true;
1878:   if (lapFrac > 0.64) p.sectors[2] = true;
1879: }
