450: function updateDrawStats(preview) {
451:   if (!preview) {
452:     dom.statLength.textContent = '—';
453:     dom.statTurns.textContent = '—';
454:     dom.statStraight.textContent = '—';
455:     dom.readoutLength.textContent = '0 m';
456:     dom.readoutTurns.textContent = '0 turns';
457:     dom.drawStatus.textContent = 'DRAW A CLOSED LOOP';
458:     dom.btnBuild.disabled = true;
459:     dom.validationInline.classList.remove('show');
460:     setValidation('error', 'CIRCUIT INCOMPLETE', 'Draw one continuous loop to unlock the build.');
461:     return;
462:   }
463: 
464:   dom.statLength.textContent = preview.length.toLocaleString();
465:   dom.statTurns.textContent = preview.turns;
466:   dom.statStraight.textContent = preview.longestStraight.toLocaleString();
467:   dom.readoutLength.textContent = `${preview.length.toLocaleString()} m`;
468:   dom.readoutTurns.textContent = `${preview.turns} turns`;
469: 
470:   if (preview.selfIntersects) {
471:     dom.drawStatus.textContent = 'SELF-INTERSECTION DETECTED';
472:     dom.btnBuild.disabled = true;
473:     setValidation('error', 'TRACK CROSSES ITSELF', 'Erase and redraw one clean loop. Bridges arrive in APEX INK 2.');
474:     dom.validationInline.textContent = 'FIX THE CROSSING';
475:     dom.validationInline.classList.add('show');
476:   } else if (preview.tooFew) {
477:     dom.drawStatus.textContent = 'KEEP DRAWING';
478:     dom.btnBuild.disabled = true;
479:     setValidation('error', 'THAT IS A SCRIBBLE', 'Hold and drag to sketch a full circuit — bigger than a dot.');
480:     dom.validationInline.textContent = 'LOOP TOO SHORT';
481:     dom.validationInline.classList.add('show');
482:   } else if (preview.tooSmall) {
483:     dom.drawStatus.textContent = 'DRAW BIGGER';
484:     dom.btnBuild.disabled = true;
485:     setValidation('error', 'A LITTLE TOO POCKET-SIZED', 'Give us a larger loop so the car has somewhere to breathe.');
486:     dom.validationInline.textContent = 'TRY A BIGGER LOOP';
487:     dom.validationInline.classList.add('show');
488:   } else if (preview.valid && preview.minRadius > 0 && preview.minRadius < 26) {
489:     dom.drawStatus.textContent = 'CIRCUIT READY · TIGHT';
490:     dom.btnBuild.disabled = false;
491:     setValidation('warning', 'TIGHT & TECHNICAL', 'Approved — but those hairpins will bite. The AI will struggle too.');
492:     dom.validationInline.classList.remove('show');
493:   } else if (preview.valid) {
494:     dom.drawStatus.textContent = 'CIRCUIT APPROVED';
495:     dom.btnBuild.disabled = false;
496:     setValidation('valid', 'CIRCUIT APPROVED', `${preview.turns} corners · start/finish locked. Ready to pour asphalt.`);
497:     dom.validationInline.textContent = 'READY TO BUILD';
498:     dom.validationInline.classList.add('show');
499:   } else {
500:     dom.drawStatus.textContent = 'DRAW A CLOSED LOOP';
501:     dom.btnBuild.disabled = true;
502:     setValidation('error', 'CIRCUIT INCOMPLETE', 'Keep the line continuous and close the loop.');
503:   }
504: }
