846: /* ═══════════════════════════════════════════════════════════════════
847:    Smoke / dust particles
848:    ═══════════════════════════════════════════════════════════════════ */
849: class SmokeSystem {
850:   constructor(scene) {
851:     this.count = 260;
852:     this.cursor = 0;
853:     this.positions = new Float32Array(this.count * 3);
854:     this.colors = new Float32Array(this.count * 3);
855:     this.sizes = new Float32Array(this.count);
856:     this.alphas = new Float32Array(this.count);
857:     this.life = new Float32Array(this.count);
858:     this.maxLife = new Float32Array(this.count);
859:     this.vel = new Float32Array(this.count * 3);
860:     this.baseSize = new Float32Array(this.count);
861:     for (let i = 0; i < this.count; i++) {
862:       this.positions[i * 3 + 1] = -999;
863:       this.alphas[i] = 0;
864:     }
865:     const geo = new THREE.BufferGeometry();
866:     geo.setAttribute('position', new THREE.BufferAttribute(this.positions, 3));
867:     geo.setAttribute('aColor', new THREE.BufferAttribute(this.colors, 3));
868:     geo.setAttribute('aSize', new THREE.BufferAttribute(this.sizes, 1));
869:     geo.setAttribute('aAlpha', new THREE.BufferAttribute(this.alphas, 1));
870:     this.geo = geo;
871:     this.material = new THREE.ShaderMaterial({
872:       transparent: true,
873:       depthWrite: false,
874:       vertexShader: `
875:         attribute float aSize;
876:         attribute float aAlpha;
877:         attribute vec3 aColor;
878:         varying float vAlpha;
879:         varying vec3 vColor;
880:         void main() {
881:           vAlpha = aAlpha;
882:           vColor = aColor;
883:           vec4 mv = modelViewMatrix * vec4(position, 1.0);
884:           gl_PointSize = aSize * (340.0 / max(1.0, -mv.z));
885:           gl_Position = projectionMatrix * mv;
886:         }
887:       `,
888:       fragmentShader: `
889:         varying float vAlpha;
890:         varying vec3 vColor;
891:         void main() {
892:           float d = length(gl_PointCoord - vec2(0.5));
893:           if (d > 0.5) discard;
894:           gl_FragColor = vec4(vColor, vAlpha * smoothstep(0.5, 0.08, d));
895:         }
896:       `
897:     });
898:     this.points = new THREE.Points(geo, this.material);
899:     this.points.frustumCulled = false;
900:     scene.add(this.points);
901:     this.dirty = false;
902:   }
903: 
904:   emit(x, y, z, color, size = 0.55, life = 1.1, spread = 1.4) {
905:     const i = this.cursor;
906:     this.cursor = (this.cursor + 1) % this.count;
907:     this.positions[i * 3] = x + (Math.random() - 0.5) * 0.5;
908:     this.positions[i * 3 + 1] = y + Math.random() * 0.2;
909:     this.positions[i * 3 + 2] = z + (Math.random() - 0.5) * 0.5;
910:     this.colors[i * 3] = color.r;
911:     this.colors[i * 3 + 1] = color.g;
912:     this.colors[i * 3 + 2] = color.b;
913:     this.vel[i * 3] = (Math.random() - 0.5) * spread;
914:     this.vel[i * 3 + 1] = 0.4 + Math.random() * spread;
915:     this.vel[i * 3 + 2] = (Math.random() - 0.5) * spread;
916:     this.life[i] = life;
917:     this.maxLife[i] = life;
918:     this.baseSize[i] = size;
919:     this.sizes[i] = size;
920:     this.alphas[i] = 0.5;
921:     this.dirty = true;
922:   }
923: 
924:   update(dt) {
925:     for (let i = 0; i < this.count; i++) {
926:       if (this.life[i] <= 0) continue;
927:       this.life[i] -= dt;
928:       if (this.life[i] <= 0) {
929:         this.alphas[i] = 0;
930:         this.positions[i * 3 + 1] = -999;
931:         this.dirty = true;
932:         continue;
933:       }
