305: export function createRaceWorld(track) {
306:   const scene = new THREE.Scene();
307:   const rng = mulberry32(track.seed);
308:   const sunDir = new THREE.Vector3(-0.55, 0.72, 0.42).normalize();
309:   const sunPos = sunDir.clone().multiplyScalar(620);
310:   const disposables = [];
311: 
312:   scene.fog = new THREE.FogExp2(0xcfd9d8, 0.00072);
313: 
314:   const sky = createSky(sunDir);
315:   scene.add(sky);
316: 
317:   // sun disc
318:   const sunMat = new THREE.SpriteMaterial({
319:     map: createCanvasTexture([256, 256], (ctx, w, h) => {
320:       const g = ctx.createRadialGradient(w / 2, h / 2, 0, w / 2, h / 2, w / 2);
321:       g.addColorStop(0, 'rgba(255,247,225,1)');
322:       g.addColorStop(0.18, 'rgba(255,224,170,.9)');
323:       g.addColorStop(0.5, 'rgba(255,180,100,.18)');
324:       g.addColorStop(1, 'rgba(255,150,60,0)');
325:       ctx.fillStyle = g;
326:       ctx.fillRect(0, 0, w, h);
327:     }),
328:     transparent: true, depthWrite: false, blending: THREE.AdditiveBlending
329:   });
330:   const sunSprite = new THREE.Sprite(sunMat);
331:   sunSprite.position.copy(sunDir).multiplyScalar(2600);
332:   sunSprite.scale.set(700, 700, 1);
333:   scene.add(sunSprite);
334: 
335:   // clouds
336:   const clouds = new THREE.Group();
337:   const cloudTex = cloudTexture();
338:   for (let i = 0; i < 10; i++) {
339:     const sprite = new THREE.Sprite(new THREE.SpriteMaterial({ map: cloudTex, transparent: true, opacity: 0.34, depthWrite: false }));
340:     const ang = rng() * TAU;
341:     const dist = 900 + rng() * 1400;
342:     sprite.position.set(Math.cos(ang) * dist, 260 + rng() * 320, Math.sin(ang) * dist);
343:     const sc = 380 + rng() * 560;
344:     sprite.scale.set(sc, sc * 0.42, 1);
345:     clouds.add(sprite);
346:   }
347:   scene.add(clouds);
348: 
349:   /* lighting */
350:   const hemi = new THREE.HemisphereLight(0xbcd4ee, 0x424c31, 1.05);
351:   scene.add(hemi);
352:   const sun = new THREE.DirectionalLight(0xffdfb8, 2.7);
353:   sun.position.copy(sunPos);
354:   sun.target.position.set(track.centerX, 0, track.centerZ);
355:   scene.add(sun.target);
356:   const shadowExtent = Math.max(track.bbox.width, track.bbox.depth) * 0.62 + 80;
357:   sun.castShadow = true;
358:   sun.shadow.mapSize.set(2048, 2048);
359:   sun.shadow.camera.left = -shadowExtent;
360:   sun.shadow.camera.right = shadowExtent;
361:   sun.shadow.camera.top = shadowExtent;
362:   sun.shadow.camera.bottom = -shadowExtent;
363:   sun.shadow.camera.near = 20;
364:   sun.shadow.camera.far = 1600;
365:   sun.shadow.bias = -0.0006;
366:   sun.shadow.normalBias = 0.02;
367:   scene.add(sun);
368:   const fill = new THREE.DirectionalLight(0x9fc2df, 0.5);
369:   fill.position.set(200, 180, -260);
370:   scene.add(fill);
371: 
372:   /* ground */
373:   const grassTex = grassTexture();
374:   disposables.push(grassTex);
375:   const groundMat = new THREE.MeshStandardMaterial({ map: grassTex, color: 0xb7b79a, roughness: 1, metalness: 0 });
376:   const groundSize = Math.max(3600, Math.max(track.bbox.width, track.bbox.depth) * 6);
377:   const ground = new THREE.Mesh(new THREE.PlaneGeometry(groundSize, groundSize), groundMat);
378:   ground.rotation.x = -Math.PI / 2;
379:   ground.position.set(track.centerX, -0.03, track.centerZ);
380:   ground.receiveShadow = true;
381:   scene.add(ground);
382: 
383:   /* road */
384:   const asphaltTex = asphaltTexture();
385:   disposables.push(asphaltTex);
386:   const roadMat = new THREE.MeshStandardMaterial({ map: asphaltTex, color: 0xd8d8d8, roughness: 0.96, metalness: 0.02 });
387:   const road = new THREE.Mesh(ribbonGeometry(track, -track.halfWidth, track.halfWidth, 0.02, { tile: 9 }), roadMat);
388:   road.receiveShadow = true;
389:   scene.add(road);
390: 
391:   // white edge lines
392:   const lineMat = new THREE.MeshStandardMaterial({ color: 0xf3eee2, roughness: 0.72, metalness: 0.02 });
393:   for (const side of [-1, 1]) {
394:     const inner = side * (track.halfWidth - 0.42);
395:     const outer = side * (track.halfWidth - 0.1);
396:     const line = new THREE.Mesh(ribbonGeometry(track, inner, outer, 0.045), lineMat);
397:     line.receiveShadow = true;
398:     scene.add(line);
399:   }
400: 
401:   // run-off outside corners
402:   const gravelTex = gravelTexture();
403:   disposables.push(gravelTex);
404:   const runoffMat = new THREE.MeshStandardMaterial({ map: gravelTex, color: 0xc4bba6, roughness: 1 });
405:   const kerbRed = new THREE.Color(0xd93a2b);
406:   const kerbWhite = new THREE.Color(0xf0eadc);
407:   const outside = (i) => (track.samples[i].k > 0 ? -1 : 1);
408:   const runoff = new THREE.Mesh(
409:     segmentRibbonGeometry(track,
410:       (i) => outside(i) * (track.halfWidth + 1.35),
411:       (i) => outside(i) * (track.halfWidth + 9.5),
412:       0.006,
413:       (i) => track.kerbFlags[i] === 1,
414:       () => new THREE.Color(1, 1, 1),
415:       9), runoffMat);
416:   runoff.receiveShadow = true;
417:   scene.add(runoff);
418: 
419:   // kerbs
420:   const kerbMat = new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.62, metalness: 0.03 });
421:   for (const side of [-1, 1]) {
422:     const kerb = new THREE.Mesh(
423:       segmentRibbonGeometry(track,
424:         (i) => side * track.halfWidth,
425:         (i) => side * (track.halfWidth + 1.35),
426:         0.052,
427:         (i) => track.kerbFlags[i] === 1,
428:         (i, band) => (band % 2 === 0 ? kerbRed : kerbWhite),
429:         2.4),
430:       kerbMat
431:     );
432:     kerb.receiveShadow = true;
433:     scene.add(kerb);
434:   }
435: 
436:   // start/finish line
437:   const checkTex = checkerTexture();
438:   disposables.push(checkTex);
439:   const checkMat = new THREE.MeshStandardMaterial({ map: checkTex, roughness: 0.75 });
440:   const startLine = planeAt(track.start, track.halfWidth * 2 - 0.5, 2.2, 0.06, checkMat);
441:   scene.add(startLine);
442: 
443:   // grid slot markings
444:   const gridMat = new THREE.MeshStandardMaterial({ color: 0xe8e2d6, roughness: 0.8 });
445:   for (let i = 0; i < 4; i++) {
446:     const dist = 8 + i * 9.5;
447:     const idx = (track.N - Math.round(dist / track.step) + track.N) % track.N;
448:     const s = track.samples[idx];
449:     const lat = i % 2 === 0 ? -3.4 : 3.4;
450:     const geo = new THREE.BoxGeometry(3.1, 0.012, 0.18);
451:     const bar = new THREE.Mesh(geo, gridMat);
452:     bar.position.set(s.x + s.nx * lat, 0.058, s.z + s.nz * lat);
453:     bar.rotation.y = Math.atan2(s.tx, s.tz);
454:     scene.add(bar);
455:   }
456: 
457:   /* ── start gantry ───────────────────────────────────────────── */
458:   const gantry = new THREE.Group();
459:   const metalMat = new THREE.MeshStandardMaterial({ color: 0x24272d, roughness: 0.45, metalness: 0.8 });
460:   const signMat = new THREE.MeshStandardMaterial({ color: 0x111318, roughness: 0.5, metalness: 0.4 });
461:   const pillarGeo = new THREE.CylinderGeometry(0.26, 0.34, 7.6, 10);
462:   for (const side of [-1, 1]) {
463:     const p = new THREE.Mesh(pillarGeo, metalMat);
464:     p.position.set(side * (track.halfWidth + 2.6), 3.8, 0);
465:     p.castShadow = true;
466:     gantry.add(p);
467:   }
468:   const beam = new THREE.Mesh(new THREE.BoxGeometry(track.halfWidth * 2 + 6, 0.75, 0.9), metalMat);
469:   beam.position.set(0, 7.25, 0);
470:   beam.castShadow = true;
471:   gantry.add(beam);
472:   const banner = new THREE.Mesh(new THREE.BoxGeometry(track.halfWidth * 1.5, 1.5, 0.15), signMat);
473:   banner.position.set(0, 6.2, 0);
474:   gantry.add(banner);
475:   const bannerTex = canvasTexture(makeTextCanvas(512, 96, (ctx, w, h) => {
476:     ctx.fillStyle = '#111318'; ctx.fillRect(0, 0, w, h);
477:     ctx.fillStyle = '#f3efe5'; ctx.font = '700 52px Rajdhani'; ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
478:     ctx.fillText('APEX INK', w / 2 - 30, h / 2 + 2);
479:     ctx.fillStyle = '#ff4d1f'; ctx.fillRect(w - 96, 0, 96, h);
480:     ctx.fillStyle = '#111318'; ctx.font = '700 30px Rajdhani'; ctx.fillText('GP', w - 48, h / 2 + 2);
481:   }));
482:   disposables.push(bannerTex);
483:   const bannerPlane = new THREE.Mesh(new THREE.PlaneGeometry(track.halfWidth * 1.5, 1.5), new THREE.MeshBasicMaterial({ map: bannerTex }));
484:   bannerPlane.position.set(0, 6.2, -0.09);
485:   bannerPlane.rotation.y = Math.PI;
486:   gantry.add(bannerPlane);
487: 
488:   const startLights = [];
489:   for (let i = 0; i < 5; i++) {
490:     const mat = new THREE.MeshStandardMaterial({ color: 0x220606, emissive: 0xff1a0a, emissiveIntensity: 0.05, roughness: 0.3 });
491:     const bulb = new THREE.Mesh(new THREE.SphereGeometry(0.17, 12, 8), mat);
492:     bulb.position.set(-1.44 + i * 0.72, 7.6, 0);
493:     gantry.add(bulb);
494:     startLights.push(mat);
495:   }
496:   gantry.position.set(track.start.x, 0, track.start.z);
497:   gantry.rotation.y = Math.atan2(track.start.tx, track.start.tz);
498:   scene.add(gantry);
499: 
500:   /* ── scenery placement helpers ───────────────────────────────── */
501:   const roadPts = [];
502:   for (let i = 0; i < track.N; i += 4) roadPts.push(track.samples[i]);
503:   const distanceToRoad = (x, z) => {
504:     let best = Infinity;
505:     for (const p of roadPts) {
506:       const d = (p.x - x) ** 2 + (p.z - z) ** 2;
507:       if (d < best) best = d;
508:     }
509:     return Math.sqrt(best);
510:   };
511:   const startPos = track.start;
512:   const nearStart = (x, z, r = 95) => Math.hypot(x - startPos.x, z - startPos.z) < r;
513:   const worldExtent = Math.max(track.bbox.width, track.bbox.depth) * 0.5 + 260;
514:   const spot = (minRoad = 20) => {
515:     for (let tries = 0; tries < 60; tries++) {
516:       const ang = rng() * TAU;
517:       const rad = Math.sqrt(rng()) * worldExtent;
518:       const x = track.centerX + Math.cos(ang) * rad;
519:       const z = track.centerZ + Math.sin(ang) * rad;
520:       if (distanceToRoad(x, z) < minRoad) continue;
521:       if (nearStart(x, z)) continue;
522:       return { x, z };
523:     }
524:     return null;
525:   };
526: 
527:   /* ── trees ───────────────────────────────────────────────────── */
528:   const treeCount = 340;
529:   const trunkGeo = new THREE.CylinderGeometry(0.22, 0.34, 2.8, 6);
530:   const trunkMat = new THREE.MeshStandardMaterial({ color: 0x554533, roughness: 0.95 });
531:   const canopyGeo = new THREE.IcosahedronGeometry(1, 1);
532:   const canopyMat = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.9, flatShading: true });
533:   const trunks = new THREE.InstancedMesh(trunkGeo, trunkMat, treeCount);
534:   const canopies = new THREE.InstancedMesh(canopyGeo, canopyMat, treeCount);
535:   trunks.castShadow = true;
536:   canopies.castShadow = true;
537:   canopies.receiveShadow = true;
538:   const greenPalette = [0x3f5f2e, 0x4b7034, 0x35552a, 0x557c3b, 0x2f4b28, 0x668c45, 0x486b30];
539:   const dummy = new THREE.Object3D();
540:   let treeIdx = 0;
541:   let guard = 0;
542:   while (treeIdx < treeCount && guard++ < 3000) {
543:     const p = spot(17);
544:     if (!p) continue;
545:     const scale = 0.7 + rng() * 1.3;
546:     const h = 2.4 + rng() * 3.4;
