612:   function standClearance(s, side, offset, width) {
613:     let min = Infinity;
614:     const front = Math.max(12, offset - 8.5);
615:     for (let k = 0; k <= 4; k++) {
616:       const lx = -width / 2 + (width * k) / 4;
617:       const px = s.x + s.tx * lx + s.nx * side * front;
618:       const pz = s.z + s.tz * lx + s.nz * side * front;
619:       for (let i = 0; i < track.N; i += 2) {
620:         const q = track.samples[i];
621:         const d = Math.hypot(q.x - px, q.z - pz);
622:         if (d < min) min = d;
623:       }
624:     }
625:     return min;
626:   }
627: 
628:   function makeGrandstand(index, width = 40) {
629:     const s = track.samples[(index + track.N) % track.N];
630:     let side = 1;
631:     let offset = track.halfWidth + 30;
632:     let clearance = -Infinity;
633:     for (const candidate of [-1, 1]) {
634:       let dist = track.halfWidth + 30;
635:       let clr = standClearance(s, candidate, dist, width);
636:       for (let attempt = 0; attempt < 3 && clr < 24; attempt++) {
637:         dist += 24 - clr + 2;
638:         clr = standClearance(s, candidate, dist, width);
639:       }
640:       if (clr > clearance) {
641:         clearance = clr;
642:         side = candidate;
643:         offset = dist;
644:       }
645:     }
646:     const g = new THREE.Group();
647:     const base = new THREE.Mesh(new THREE.BoxGeometry(width, 1.2, 17), standConcrete);
648:     base.position.y = 0.6;
649:     base.receiveShadow = true; base.castShadow = true;
650:     g.add(base);
651:     const seating = new THREE.Mesh(new THREE.BoxGeometry(width - 2, 7.4, 13), standDark);
652:     seating.position.set(0, 4.6, 0.6);
653:     seating.rotation.x = -0.12;
654:     seating.castShadow = true;
655:     g.add(seating);
656:     const crowd = new THREE.Mesh(new THREE.PlaneGeometry(width - 3, 6.8), crowdMat);
657:     crowd.position.set(0, 4.4, -5.4);
658:     crowd.rotation.x = 0.1;
659:     g.add(crowd);
660:     const roof = new THREE.Mesh(new THREE.BoxGeometry(width + 3, 0.45, 18), standRoof);
661:     roof.position.set(0, 10.1, -1);
662:     roof.rotation.x = 0.06;
663:     roof.castShadow = true;
664:     g.add(roof);
665:     for (const x of [-width / 2 + 2, 0, width / 2 - 2]) {
666:       const col = new THREE.Mesh(new THREE.BoxGeometry(0.35, 9.6, 0.35), standDark);
667:       col.position.set(x, 5.1, -8.4);
668:       g.add(col);
669:     }
670:     const trim = new THREE.Mesh(new THREE.BoxGeometry(width, 0.25, 0.3), new THREE.MeshStandardMaterial({ color: 0xff4d1f, emissive: 0x3a0c02, emissiveIntensity: 0.4 }));
671:     trim.position.set(0, 10.35, -9.8);
672:     g.add(trim);
673:     g.position.set(s.x + s.nx * side * offset, 0, s.z + s.nz * side * offset);
674:     g.rotation.y = Math.atan2(s.tx, s.tz) + (side > 0 ? -Math.PI / 2 : Math.PI / 2);
675:     scene.add(g);
676:     return g;
677:   }
