22: function loft(sections, material, { radial = 14, power = 0.62 } = {}) {
23:   const positions = [];
24:   const indices = [];
25:   const rings = sections.map((s) => superellipseRing(s.w, s.h, radial, power).map((p) => [p.x, s.y + p.y, s.z]));
26:   for (let i = 0; i < rings.length; i++) {
27:     const ring = rings[i];
28:     for (const p of ring) positions.push(...p);
29:   }
30:   for (let i = 0; i < rings.length - 1; i++) {
31:     for (let j = 0; j < radial; j++) {
32:       const a = i * radial + j;
33:       const b = i * radial + ((j + 1) % radial);
34:       const c = (i + 1) * radial + j;
35:       const d = (i + 1) * radial + ((j + 1) % radial);
36:       // Counter-clockwise from outside so front-face culling keeps the hull solid.
37:       indices.push(a, b, c, b, d, c);
38:     }
39:   }
40:   // caps
41:   const firstCenter = positions.length / 3;
42:   positions.push(0, sections[0].y, sections[0].z);
43:   for (let j = 0; j < radial; j++) {
44:     indices.push(firstCenter, (j + 1) % radial, j);
45:   }
46:   const lastBase = (rings.length - 1) * radial;
47:   const lastCenter = positions.length / 3;
48:   positions.push(0, sections[sections.length - 1].y, sections[sections.length - 1].z);
49:   for (let j = 0; j < radial; j++) {
50:     indices.push(lastCenter, lastBase + j, lastBase + ((j + 1) % radial));
51:   }
52:   const geo = new THREE.BufferGeometry();
53:   geo.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
54:   geo.setIndex(indices);
55:   geo.computeVertexNormals();
56:   const mesh = new THREE.Mesh(geo, material);
57:   mesh.castShadow = true;
58:   return mesh;
59: }
