61: function topStripe(sections, width, material) {
62:   const positions = [];
63:   const indices = [];
64:   const half = width / 2;
65:   sections.forEach((s, i) => {
66:     const y = s.y + s.h + 0.012;
67:     positions.push(-half, y, s.z, half, y, s.z);
68:     if (i > 0) {
69:       const a = (i - 1) * 2;
70:       indices.push(a, a + 2, a + 1, a + 1, a + 2, a + 3);
71:     }
72:   });
73:   const geo = new THREE.BufferGeometry();
74:   geo.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
75:   geo.setIndex(indices);
76:   geo.computeVertexNormals();
77:   const mesh = new THREE.Mesh(geo, material);
78:   mesh.castShadow = false;
79:   return mesh;
80: }
