105: function drawStarPath(ctx, cx, cy, outer, inner, points = 5) {
106:   ctx.beginPath();
107:   for (let i = 0; i < points * 2; i++) {
108:     const angle = -Math.PI / 2 + (i / (points * 2)) * TAU;
109:     const radius = i % 2 === 0 ? outer : inner;
110:     const x = cx + Math.cos(angle) * radius;
111:     const y = cy + Math.sin(angle) * radius;
112:     if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
113:   }
114:   ctx.closePath();
115: }
