117: function makeStickerTexture(type, color) {
118:   const canvas = makeTextCanvas(512, 256, (ctx, w, h) => {
119:     ctx.clearRect(0, 0, w, h);
120:     ctx.fillStyle = color;
121:     ctx.strokeStyle = color;
122:     ctx.lineCap = 'round';
123:     ctx.lineJoin = 'round';
124:     ctx.textAlign = 'center';
125:     ctx.textBaseline = 'middle';
126: 
127:     switch (type) {
128:       case 'number':
129:         ctx.font = '700 190px Rajdhani, sans-serif';
130:         ctx.fillText('07', w / 2, h / 2 + 8);
131:         break;
132:       case 'apex': {
133:         ctx.font = '700 112px Rajdhani, sans-serif';
134:         ctx.fillText('APEX', w / 2, h / 2 - 18);
135:         ctx.font = '600 38px Rajdhani, sans-serif';
136:         ctx.globalAlpha = 0.8;
137:         ctx.fillText('I N K', w / 2, h / 2 + 64);
138:         ctx.globalAlpha = 1;
139:         break;
140:       }
141:       case 'stripe':
142:         ctx.save();
143:         ctx.translate(w / 2, h / 2);
144:         ctx.rotate(-0.3);
145:         for (let i = -1; i <= 1; i++) ctx.fillRect(-178, i * 42 - 9, 356, 18);
146:         ctx.restore();
147:         break;
148:       case 'bolt': {
149:         ctx.beginPath();
150:         ctx.moveTo(285, 26);
151:         ctx.lineTo(138, 144);
152:         ctx.lineTo(242, 144);
153:         ctx.lineTo(205, 230);
154:         ctx.lineTo(374, 100);
155:         ctx.lineTo(264, 100);
156:         ctx.closePath();
157:         ctx.fill();
158:         break;
159:       }
160:       case 'star':
161:         drawStarPath(ctx, w / 2, h / 2, 104, 45, 5);
162:         ctx.fill();
163:         break;
164:       case 'checker': {
165:         const size = 34;
166:         const cols = 6;
167:         const rows = 3;
168:         const ox = w / 2 - (cols * size) / 2;
169:         const oy = h / 2 - (rows * size) / 2;
170:         for (let y = 0; y < rows; y++) {
171:           for (let x = 0; x < cols; x++) {
172:             if ((x + y) % 2 === 0) ctx.fillRect(ox + x * size, oy + y * size, size - 3, size - 3);
173:           }
174:         }
175:         break;
176:       }
177:       case 'flame': {
178:         ctx.beginPath();
179:         ctx.moveTo(256, 28);
180:         ctx.bezierCurveTo(350, 92, 352, 154, 306, 198);
181:         ctx.bezierCurveTo(326, 150, 286, 132, 268, 174);
182:         ctx.bezierCurveTo(252, 136, 210, 150, 218, 196);
183:         ctx.bezierCurveTo(166, 152, 184, 90, 256, 28);
184:         ctx.closePath();
185:         ctx.fill();
186:         ctx.globalCompositeOperation = 'destination-out';
187:         ctx.beginPath();
188:         ctx.moveTo(258, 132);
189:         ctx.bezierCurveTo(292, 158, 288, 188, 258, 206);
190:         ctx.bezierCurveTo(232, 180, 232, 156, 258, 132);
191:         ctx.closePath();
192:         ctx.fill();
193:         ctx.globalCompositeOperation = 'source-over';
194:         break;
195:       }
196:       default:
197:         break;
198:     }
199:   });
200:   return canvasTexture(canvas);
201: }
