214: function makeWheel(front, accentMat) {
215:   const radius = front ? 0.355 : 0.395;
216:   const width = front ? 0.34 : 0.46;
217:   const steer = new THREE.Group();
218:   const spin = new THREE.Group();
219:   steer.add(spin);
220: 
221:   const rubber = new THREE.MeshStandardMaterial({ color: 0x0c0d0f, roughness: 0.92, metalness: 0.05 });
222:   const rimMat = new THREE.MeshStandardMaterial({ color: 0x2c2f34, roughness: 0.35, metalness: 0.9 });
223: 
224:   const tireGeo = new THREE.CylinderGeometry(radius, radius, width, 28, 1);
225:   tireGeo.rotateZ(Math.PI / 2);
226:   const tire = new THREE.Mesh(tireGeo, rubber);
227:   tire.castShadow = true;
228:   spin.add(tire);
229: 
230:   // sidewall rings
231:   for (const side of [-1, 1]) {
232:     const ring = new THREE.Mesh(new THREE.TorusGeometry(radius * 0.79, 0.012, 6, 32), accentMat);
233:     ring.rotation.y = Math.PI / 2;
234:     ring.position.x = side * (width / 2 + 0.004);
235:     spin.add(ring);
236:   }
237: 
238:   // rim + spokes
239:   const rimGeo = new THREE.CylinderGeometry(radius * 0.6, radius * 0.6, width + 0.01, 24, 1);
240:   rimGeo.rotateZ(Math.PI / 2);
241:   const rim = new THREE.Mesh(rimGeo, rimMat);
242:   spin.add(rim);
243: 
244:   for (let k = 0; k < 5; k++) {
245:     const spoke = new THREE.Mesh(new THREE.BoxGeometry(width * 0.5, 0.045, radius * 1.24), rimMat);
246:     spoke.rotation.x = (k / 5) * Math.PI;
247:     spin.add(spoke);
248:   }
249:   const hub = new THREE.Mesh(new THREE.CylinderGeometry(0.075, 0.075, width + 0.08, 12), accentMat);
250:   hub.geometry.rotateZ(Math.PI / 2);
251:   spin.add(hub);
252: 
253:   return { steer, spin, radius, width };
254: }
