1734: function nearestTrackSample(track, x, z, hint = -1, windowMeters = 26) {
1735:   const N = track.N;
1736:   let best = -1;
1737:   let bestD = Infinity;
1738:   if (Number.isInteger(hint) && hint >= 0 && hint < N) {
1739:     const span = Math.max(6, Math.round(windowMeters / track.step));
1740:     for (let k = -span; k <= span; k++) {
1741:       const i = (hint + k + N) % N;
1742:       const s = track.samples[i];
1743:       const d = (s.x - x) ** 2 + (s.z - z) ** 2;
1744:       if (d < bestD) { bestD = d; best = i; }
1745:     }
1746:     // If the car is well off the road (or has been recovered), fall back to the
1747:     // spatial lookup so it can always find its way back to the nearest asphalt.
1748:     if (best >= 0 && bestD > (track.halfWidth + 36) ** 2) {
1749:       const global = race.locator.nearest(x, z);
1750:       const d = global.dist * global.dist;
1751:       if (global.index >= 0 && d < bestD) { bestD = d; best = global.index; }
1752:     }
1753:   }
1754:   if (best < 0) {
1755:     const global = race.locator.nearest(x, z);
1756:     best = global.index >= 0 ? global.index : 0;
1757:     bestD = global.dist * global.dist;
1758:   }
1759:   return { index: best, dist: Math.sqrt(bestD) };
1760: }
