1810: function nearestTrackSample(track, x, z, hint = -1, windowMeters = 26) {
1811:   const N = track.N;
1812:   let best = -1;
1813:   let bestD = Infinity;
1814:   if (Number.isInteger(hint) && hint >= 0 && hint < N) {
1815:     const span = Math.max(6, Math.round(windowMeters / track.step));
1816:     for (let k = -span; k <= span; k++) {
1817:       const i = (hint + k + N) % N;
1818:       const s = track.samples[i];
1819:       const d = (s.x - x) ** 2 + (s.z - z) ** 2;
1820:       if (d < bestD) { bestD = d; best = i; }
1821:     }
1822:     // If the car is well off the road (or has been recovered), fall back to the
1823:     // spatial lookup so it can always find its way back to the nearest asphalt.
1824:     if (best >= 0 && bestD > (track.halfWidth + 36) ** 2) {
1825:       const global = race.locator.nearest(x, z);
1826:       const d = global.dist * global.dist;
1827:       if (global.index >= 0 && d < bestD) { bestD = d; best = global.index; }
1828:     }
1829:   }
1830:   if (best < 0) {
1831:     const global = race.locator.nearest(x, z);
1832:     best = global.index >= 0 ? global.index : 0;
1833:     bestD = global.dist * global.dist;
1834:   }
1835:   return { index: best, dist: Math.sqrt(bestD) };
1836: }
