1936: function updatePlayerProgress(dt) {
1937:   const p = race.player;
1938:   if (p.finished) return;
1939:   const tr = race.track;
1940:   const L = tr.length;
1941:   const near = nearestTrackSample(tr, p.pos.x, p.pos.z, p.lastIndex);
1942:   const candidate = unwrapTrackDistance(
1943:     trackDistanceAt(tr, near.index, p.pos.x, p.pos.z),
1944:     p.progressDist,
1945:     L
1946:   );
1947: 
1948:   // A car can only advance a sensible distance in one physics step. Clamping
1949:   // rejected huge jumps from nearby track sections while still letting the
1950:   // progress catch up after a recovery.
1951:   const allowed = Math.max(16, Math.abs(p.vLong) * Math.max(dt, 0.001) * 4 + 3);
1952:   const delta = candidate - p.progressDist;
1953:   p.progressDist += Math.abs(delta) <= allowed ? delta : clamp(delta, -allowed, allowed);
1954:   p.lastIndex = near.index;
1955:   p.trackDist = near.dist;
1956:   p.sNorm = (((p.progressDist % L) + L) % L) / L;
