1837: function nearestTrackSample(track, x, z, hint = -1, windowMeters = 26) {
1838:   const N = track.N;
1839:   let best = -1;
1840:   let bestD = Infinity;
1841:   if (Number.isInteger(hint) && hint >= 0 && hint < N) {
1842:     const span = Math.max(6, Math.round(windowMeters / track.step));
1843:     for (let k = -span; k <= span; k++) {
1844:       const i = (hint + k + N) % N;
1845:       const s = track.samples[i];
1846:       const d = (s.x - x) ** 2 + (s.z - z) ** 2;
1847:       if (d < bestD) { bestD = d; best = i; }
1848:     }
1849:     // If the car is well off the road (or has been recovered), fall back to the
1850:     // spatial lookup so it can always find its way back to the nearest asphalt.
1851:     if (best >= 0 && bestD > (track.halfWidth + 36) ** 2) {
1852:       const global = race.locator.nearest(x, z);
1853:       const d = global.dist * global.dist;
1854:       if (global.index >= 0 && d < bestD) { bestD = d; best = global.index; }
1855:     }
1856:   }
1857:   if (best < 0) {
1858:     const global = race.locator.nearest(x, z);
1859:     best = global.index >= 0 ? global.index : 0;
1860:     bestD = global.dist * global.dist;
1861:   }
1862:   return { index: best, dist: Math.sqrt(bestD) };
1863: }
