1847: function nearestTrackSample(track, x, z, hint = -1, windowMeters = 26) {
1848:   const N = track.N;
1849:   let best = -1;
1850:   let bestD = Infinity;
1851:   if (Number.isInteger(hint) && hint >= 0 && hint < N) {
1852:     const span = Math.max(6, Math.round(windowMeters / track.step));
1853:     for (let k = -span; k <= span; k++) {
1854:       const i = (hint + k + N) % N;
1855:       const s = track.samples[i];
1856:       const d = (s.x - x) ** 2 + (s.z - z) ** 2;
1857:       if (d < bestD) { bestD = d; best = i; }
1858:     }
1859:     // If the car is well off the road (or has been recovered), fall back to the
1860:     // spatial lookup so it can always find its way back to the nearest asphalt.
1861:     if (best >= 0 && bestD > (track.halfWidth + 36) ** 2) {
1862:       const global = race.locator.nearest(x, z);
1863:       const d = global.dist * global.dist;
1864:       if (global.index >= 0 && d < bestD) { bestD = d; best = global.index; }
1865:     }
1866:   }
1867:   if (best < 0) {
1868:     const global = race.locator.nearest(x, z);
1869:     best = global.index >= 0 ? global.index : 0;
1870:     bestD = global.dist * global.dist;
1871:   }
1872:   return { index: best, dist: Math.sqrt(bestD) };
